CREATE TABLE IF NOT EXISTS public.atlas_usuarios (id integer GENERATED BY DEFAULT AS IDENTITY, username varchar NOT NULL, nome_exibicao varchar, papel varchar NOT NULL, ativo boolean, tentativas_falhas integer, bloqueado_ate timestamp, criado_em timestamp, almoxarifados_permitidos json, google_conectado_email varchar, slack_conectado_user_id varchar, slack_conectado_team_id varchar, profile_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, PRIMARY KEY (id));

