-- Controle da importação do backup
CREATE TABLE IF NOT EXISTS public.atlas_importacoes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tabela text NOT NULL,
  linhas_backup int,
  linhas_importadas int,
  gerado_em timestamptz,          -- data do backup (manifesto.json)
  importado_em timestamptz NOT NULL DEFAULT now(),
  importado_por uuid DEFAULT auth.uid()
);

-- RLS: leitura para usuários logados (usuarios, log_auditoria e o controle de importação só gestor); escrita só gestor
DO $$ DECLARE t text; BEGIN
  FOR t IN SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' AND table_name LIKE 'atlas\_%' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (%s)', t || '_read', t,
      CASE WHEN t IN ('atlas_log_auditoria', 'atlas_usuarios', 'atlas_importacoes') THEN 'public.is_gestor(auth.uid())' ELSE 'true' END);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING (public.is_gestor(auth.uid())) WITH CHECK (public.is_gestor(auth.uid()))', t || '_gestor', t);
  END LOOP;
END $$;

-- Depois de importar com os ids originais, alinha cada identidade ao maior id (novos registros não colidem).
CREATE OR REPLACE FUNCTION public.atlas_ajustar_sequencias()
RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE r record; seq text; n int := 0;
BEGIN
  IF NOT public.is_gestor(auth.uid()) THEN RAISE EXCEPTION 'Apenas gestor'; END IF;
  FOR r IN SELECT c.table_name FROM information_schema.columns c
           WHERE c.table_schema = 'public' AND c.table_name LIKE 'atlas\_%' AND c.column_name = 'id' AND c.is_identity = 'YES' LOOP
    seq := pg_get_serial_sequence('public.' || quote_ident(r.table_name), 'id');
    IF seq IS NOT NULL THEN
      EXECUTE format('SELECT setval(%L, GREATEST(COALESCE((SELECT max(id) FROM public.%I), 0), 1), (SELECT count(*) > 0 FROM public.%I))', seq, r.table_name, r.table_name);
      n := n + 1;
    END IF;
  END LOOP;
  RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.atlas_ajustar_sequencias() FROM public, anon;
GRANT EXECUTE ON FUNCTION public.atlas_ajustar_sequencias() TO authenticated;
